/* ============================================================
   __tsMO — gebremste MutationObserver-Fabrik (02.08.2026, Performance).
   ALLE Modul-Observer dieser Datei laufen hierdurch: Leading-Edge-Aufruf
   sofort, danach 180ms-Sammelfenster (ein Trailing-Aufruf, wenn in der
   Zwischenzeit weitere Mutationen kamen). Vorher feuerten 158 site-weite
   Observer UNGEBREMST bei jeder DOM-Mutation (Tipp-Animationen = 1 Mutation
   pro Buchstabe x 158 Callbacks = Ruckeln). Kein Callback nutzt die
   Mutations-Argumente (geprueft 02.08.2026). Verhalten identisch, nur
   koalesziert. NICHT window.MutationObserver patchen -- super.so/Next
   braucht das native Verhalten.
   ============================================================ */
window.__tsMO = function(cb){
  var t=null, dirty=false;
  function fire(){ t=setTimeout(function(){ t=null; if(dirty){ dirty=false; fire(); } }, 180); try{ cb(); }catch(e){} }
  return new MutationObserver(function(){ if(t){ dirty=true; return; } fire(); });
};

/* ============================================================
   TS Lazy-Video (02.08.2026, Performance -- Robert-Befund: DB III/IV/V
   brauchten 30s+). Notion liefert die Lektions-Videos als <video> mit
   fester src aus. Chrome zieht die (teils 50-100 MB) SOFORT beim
   Seitenaufbau -- gemessen 60s Dauerdownload -- und blockiert damit
   Verbindungen, die die sichtbaren Inhalte brauchen. Die Videos sind
   auf den MacBook-Cover-Seiten sogar unsichtbar (Cover davor) und
   werden beim Klick ohnehin als NEUES <video> in der Lightbox gebaut.
   Loesung: src beim ersten Zugriff abklemmen (-> data-tssrc), preload
   auf none, laufenden Download per load() abbrechen. Zurueckgegeben
   wird die src erst, wenn das Video wirklich sichtbar in den Viewport
   kommt (IntersectionObserver, 300px Vorlauf) oder jemand darauf
   klickt. Optik unveraendert: Poster/Player-Rahmen bleiben stehen.
   Die Lightbox-Module lesen die Quelle ueber data-tssrc (5 Stellen).
   ============================================================ */
(function(){
  if(window.__tsLazyVid) return; window.__tsLazyVid=true;

  function disarm(v){
    if(v.__tsDisarmed) return; v.__tsDisarmed=true;
    var s=v.getAttribute('src')||v.currentSrc||'';
    var so=v.querySelector('source');
    if(!s && so) s=so.getAttribute('src')||'';
    if(!s) return;
    v.setAttribute('data-tssrc', s);
    v.removeAttribute('src');
    if(so){ so.setAttribute('data-tssrc', so.getAttribute('src')||''); so.removeAttribute('src'); }
    v.setAttribute('preload','none');
    try{ v.load(); }catch(e){}   /* bricht den laufenden Download ab */
  }

  function arm(v){
    if(!v.__tsDisarmed || v.__tsArmed) return; v.__tsArmed=true;
    var s=v.getAttribute('data-tssrc'); if(!s) return;
    var so=v.querySelector('source');
    if(so && so.getAttribute('data-tssrc')) so.setAttribute('src', so.getAttribute('data-tssrc'));
    v.setAttribute('src', s);
    v.setAttribute('preload','metadata');
    try{ v.load(); }catch(e){}
  }

  var io = ('IntersectionObserver' in window) ? new IntersectionObserver(function(entries){
    for(var i=0;i<entries.length;i++){
      var e=entries[i];
      if(e.isIntersecting){ arm(e.target); io.unobserve(e.target); }
    }
  }, {rootMargin:'300px'}) : null;

  function sichtbar(v){
    /* hinter einem MacBook-Cover (.tsmac-host) oder per CSS versteckt -> nicht laden */
    if(v.closest && v.closest('.tsmac-host')) return false;
    return v.offsetParent !== null || getComputedStyle(v).position === 'fixed';
  }

  function scan(){
    var vids=document.querySelectorAll('video');
    for(var i=0;i<vids.length;i++){
      var v=vids[i];
      if(v.closest && v.closest('#tsmac-lb')) continue;      /* Lightbox-Video: soll laden */
      if(v.autoplay) continue;                                /* Autoplay-Deko nicht anfassen */
      disarm(v);
      if(io && !v.__tsArmed && sichtbar(v)) io.observe(v);
    }
  }

  scan();
  document.addEventListener('DOMContentLoaded', scan);
  window.addEventListener('load', scan);
  window.__tsMO(scan).observe(document.documentElement,{childList:true,subtree:true});

  /* Klick auf den Player-Bereich -> sofort laden und abspielen */
  document.addEventListener('click', function(ev){
    var v=ev.target && ev.target.closest ? ev.target.closest('.notion-video') : null;
    if(!v) return;
    var vid=v.querySelector('video'); if(!vid) return;
    arm(vid);
  }, true);
})();

/* ============================================================
   TASTY STUDIOS · Gastronomie AI MasterClass
   kurs.js — ausgelagerte Interaktionen (super.so -> extern)
   Byte-genau aus dem Live-DOM extrahiert 2026-07-09.
   ============================================================ */

/* ============================================================
   Sidebar-Styling-Spans (Farben/Font kommen aus kurs.css, hier nur die Spans):
   1. Modul-Titel: Zahl in "Modul N" in unser Rot (.ts-modul-num) — Wort weiß / Zahl rot.
   2. Lektionen: Name NACH "//" beige (.ts-lektion-name) — "Lektion 2.1 //" bleibt weiß.
   Site-weit, selbstheilend via debounced Observer (Muster wie ts-m2-gold).
   BEWUSST AM DATEIANFANG platziert: der frühere Platz am Dateiende wurde wiederholt von
   Parallel-Commits (ad33dbc, 0b76635) beim Anhängen neuer Blöcke überschrieben. Am Anfang
   arbeitet niemand -> kollisionssicher. Bitte hier lassen.
   ============================================================ */

/* TS Page-Veil Ausloeser (Gegenstueck zum Veil-Block am Anfang von kurs.css):
   Reveal ~350ms nach DOMContentLoaded -- bis dahin haben die Seiten-Module ihren
   ersten Mount-Durchlauf gemacht. Mehrfach abgesichert: load-Event, visibility-
   change (hidden Tabs drosseln Timer/Animationen), harter 2,2s-Timeout. CSS-
   Failsafe (2,5s) greift zusaetzlich, falls dieses Skript nie ausgefuehrt wird. */
(function(){
  if(window.__tsVeil) return; window.__tsVeil=true;
  var lastMut = performance.now();
  var mo = new MutationObserver(function(){ lastMut = performance.now(); });
  mo.observe(document.documentElement, {childList:true, subtree:true, attributes:true});
  function reveal(){
    document.documentElement.classList.add('ts-reveal');
    try{ mo.disconnect(); }catch(e){}
  }
  /* Reveal, sobald das DOM nach DOMContentLoaded 300ms lang ruhig war
     (= Module fertig gemountet), fruehestens 400ms nach Skript-Start.
     WICHTIG: max. 900ms warten -- Seiten mit Dauer-Animationen (tickende
     Uhr, Tipp-Effekt) werden nie "ruhig" und sollen trotzdem zackig oeffnen. */
  var t0 = performance.now(), dclDone = document.readyState !== 'loading';
  document.addEventListener('DOMContentLoaded', function(){ dclDone = true; });
  var iv = setInterval(function(){
    var now = performance.now();
    if(dclDone && now - t0 > 400 && (now - lastMut > 300 || now - t0 > 900)){ clearInterval(iv); reveal(); }
  }, 100);
  window.addEventListener('load', function(){ setTimeout(reveal, 400); });
  document.addEventListener('visibilitychange', function(){ if(!document.hidden) setTimeout(reveal, 400); });
  setTimeout(function(){ clearInterval(iv); reveal(); }, 2200);
})();

(function(){
  if(window.__tsSbNum) return; window.__tsSbNum = true;

  /* Modul-Header: erste Ziffernfolge rot wrappen */
  function wrapModulNum(){
    document.querySelectorAll('.super-navigation-menu__list-header .super-navigation-menu__item-title').forEach(function(el){
      if(el.querySelector('.ts-modul-num')) return;
      var w=document.createTreeWalker(el, NodeFilter.SHOW_TEXT), n;
      while(n=w.nextNode()){
        var m=n.nodeValue.match(/\d+/);
        if(m){
          var after=n.splitText(m.index); after.splitText(m[0].length);
          var span=document.createElement('span'); span.className='ts-modul-num'; span.textContent=m[0];
          after.parentNode.replaceChild(span, after);
          break;
        }
      }
    });
  }

  /* Lektionen (Leaf-Links, NICHT in einem list-header): alles nach "//" beige wrappen */
  function wrapLektionName(){
    document.querySelectorAll('.super-navigation-menu__item-title').forEach(function(el){
      if(el.closest('.super-navigation-menu__list-header')) return;
      if(el.querySelector('.ts-lektion-name')) return;
      var w=document.createTreeWalker(el, NodeFilter.SHOW_TEXT), n;
      while(n=w.nextNode()){
        var i=n.nodeValue.indexOf('//');
        if(i>-1){
          var after=n.splitText(i+2);
          var span=document.createElement('span'); span.className='ts-lektion-name'; span.textContent=after.nodeValue;
          after.parentNode.replaceChild(span, after);
          break;
        }
      }
    });
  }


  /* Modul-Startseite aus der Seitenleiste erreichbar machen (Robert 02.08.2026).
     Die Gruppen-Kopfzeile ist bei super.so reines Aufklapp-Element ohne Link — man kam
     nie auf die Modul-Uebersicht. Loesung: NUR der Titel-TEXT wird ein Link (inline,
     also exakt so breit wie die Schrift). Der restliche Balken und der Pfeil bleiben
     unveraendert Aufklapp-Flaeche, deshalb stopPropagation nur auf dem <a> selbst.
     Zuordnung ueber die Modulnummer im Titel; unbekannte Nummer -> kein Link. */
  var MODUL_SLUG = {
    '0':'/modul-0-einleitung-was-dich-erwartet',
    '1':'/modul-1-notion-grundlagen-3-lernpfade',
    '2':'/modul-2-das-notion-ai-backoffice-system',
    '3':'/modul-3-dein-persnlicher-workspace',
    '4':'/modul-4-claude-claude-code',
    '5':'/modul-5-claude-code-notion',
    '6':'/modul-6-weitere-tools-projektmanagement'
  };
  function linkModulTitel(){
    document.querySelectorAll('.super-navigation-menu__list-header .super-navigation-menu__item-title').forEach(function(el){
      if(el.querySelector('a.ts-modlink')) return;
      var num=(el.textContent.match(/\d+/)||[])[0];
      var href=MODUL_SLUG[num];
      if(!href) return;
      var a=document.createElement('a');
      a.className='ts-modlink'; a.href=href;
      while(el.firstChild) a.appendChild(el.firstChild);
      el.appendChild(a);
      /* Klick auf den Text navigiert und klappt NICHT auf/zu. */
      a.addEventListener('click', function(e){ e.stopPropagation(); });
      a.addEventListener('pointerdown', function(e){ e.stopPropagation(); });
      a.addEventListener('mousedown', function(e){ e.stopPropagation(); });
    });
  }
  /* KEINE optische Kennzeichnung (Robert 03.08.2026): kein Unterstrich, kein Farbwechsel,
     kein Hover-Effekt. Der Titel soll exakt aussehen wie jeder andere Gruppentitel — der Link
     ist nur Funktion. Deshalb ausschliesslich Vererbung, nichts Eigenes. */
  var LINKCSS='.super-navigation-menu__list-header .ts-modlink{display:inline;color:inherit;font:inherit;'
    +'text-decoration:none;border:0;background:none;cursor:inherit}'
    +'.super-navigation-menu__list-header .ts-modlink:hover,'
    +'.super-navigation-menu__list-header .ts-modlink:focus,'
    +'.super-navigation-menu__list-header .ts-modlink:active{color:inherit;text-decoration:none;border:0}';
  function injectLinkCSS(){
    if(document.getElementById('ts-modlink-css')) return;
    var st=document.createElement('style'); st.id='ts-modlink-css'; st.textContent=LINKCSS;
    document.head.appendChild(st);
  }

  function apply(){ wrapModulNum(); wrapLektionName(); injectLinkCSS(); linkModulTitel(); }

  apply();
  document.addEventListener('DOMContentLoaded', apply);
  var _t=null;
  window.__tsMO(function(){ if(_t) return; _t=setTimeout(function(){ _t=null; apply(); },200); })
    .observe(document.documentElement,{childList:true,subtree:true});
})();

/* ============================================================
   Sidebar-Collapsible-Haenger-Fix (2026-07-22, Scroll-Fix v6 — ersetzt v5).
   Robert-Repro 1: Modul 1 dann Modul 2 kurz hintereinander aufklappen -> Liste "abgehackt".
   Robert-Repro 2 (v5 hat das NICHT erwischt): auch ein einzelner Klick auf Modul 2 reicht —
   die letzten 1-2 Eintraege ("Lektion 2.9.1", "2.9.2") fehlten dann komplett, kein Scrollen
   half (keine Bewegung, kein Leerraum). Ursache: Radix' eigene Aufklapp-Animation
   (@keyframes slideDown, .18s, animation-fill-mode:forwards) auf
   .super-navigation-menu__list-items[data-state="open"] bleibt bei "height:0" haengen ODER
   die von Radix selbst gemessene Zielhoehe (--radix-collapsible-content-height) ist zu kurz
   bzw. fehlt ganz (live beobachtet: leerer Wert, obwohl 21 Lektionen im DOM stehen) — v5
   verliess sich auf genau diesen Radix-Wert und griff deshalb in Robert-Repro 2 gar nicht.
   v6 misst nichts mehr und vertraut auch Radix' Wert nicht: Animation stoppen und Hoehe auf
   "auto" setzen — der Browser layoutet dann live und immer korrekt anhand des echten
   Inhalts, unabhaengig davon was Radix zwischenzeitlich (falsch) gemessen hat. */
(function(){
  if(window.__tsSbCollapsibleFix) return; window.__tsSbCollapsibleFix = true;
  function fix(){
    document.querySelectorAll('.super-navigation-menu__list-items[data-state="open"]').forEach(function(el){
      if(el.style.getPropertyValue('height') === 'auto') return;
      el.style.setProperty('animation','none','important');
      el.style.setProperty('height','auto','important');
    });
  }
  fix();
  document.addEventListener('DOMContentLoaded', fix);
  var _t=null;
  window.__tsMO(function(){ if(_t) return; _t=setTimeout(function(){ _t=null; fix(); },250); })
    .observe(document.documentElement,{childList:true,subtree:true,attributes:true,attributeFilter:['data-state','style']});
})();

(function () {
  var SEL = '.notion-toggle[class*="notion-toggle-heading"]';
  var booted = false;
  function party() {
    var c = document.createElement('canvas');
    c.style.cssText = 'position:fixed;inset:0;width:100vw;height:100vh;pointer-events:none;z-index:2147483647;';
    document.body.appendChild(c);
    var ctx = c.getContext('2d');
    var dpr = Math.min(window.devicePixelRatio || 1, 2), vw = innerWidth, vh = innerHeight;
    c.width = vw * dpr; c.height = vh * dpr; ctx.scale(dpr, dpr);
    var colors = ['#F5D77A','#EFE3B8','#FFFFFF','#A9DcC1','#E7B7A3','#D9C27A','#C9A94E'];
    var parts = [];
    function burst(cx) {
      for (var i = 0; i < 90; i++) {
        var a = -Math.PI/2 + (Math.random()-0.5)*(Math.PI*0.62);
        var sp = 13 + Math.random()*13;
        parts.push({ x: cx+(Math.random()-0.5)*50, y: vh+12,
          vx: Math.cos(a)*sp, vy: Math.sin(a)*sp, g: 0.22+Math.random()*0.10,
          w: 5+Math.random()*7, h: 9+Math.random()*9, rot: Math.random()*6.28,
          vr: (Math.random()-0.5)*0.35, color: colors[(Math.random()*colors.length)|0],
          life: 0, ttl: 120+Math.random()*50, drag: 0.988 });
      }
    }
    burst(vw*0.5); setTimeout(function(){burst(vw*0.3);},160); setTimeout(function(){burst(vw*0.7);},300);
    var frame = 0;
    (function tick() {
      frame++; ctx.clearRect(0,0,vw,vh);
      for (var i = parts.length-1; i >= 0; i--) {
        var p = parts[i];
        p.vx *= p.drag; p.vy = p.vy*p.drag + p.g; p.x += p.vx; p.y += p.vy; p.rot += p.vr; p.life++;
        var al = p.life < 16 ? 1 : Math.max(0, 1-(p.life-16)/(p.ttl-16));
        ctx.save(); ctx.globalAlpha = al; ctx.translate(p.x, p.y); ctx.rotate(p.rot);
        ctx.fillStyle = p.color; ctx.fillRect(-p.w/2, -p.h/2, p.w, p.h); ctx.restore();
        if (p.life > p.ttl || p.y > vh+50) parts.splice(i, 1);
      }
      if (parts.length && frame < 520) requestAnimationFrame(tick); else c.remove();
    })();
  }
  function decorate() {
    document.querySelectorAll(SEL).forEach(function (block, i) {
      var sum = block.querySelector(':scope > .notion-toggle__summary');
      if (!sum || sum.querySelector('.done-check')) return;
      var key = 'done-' + ((sum.textContent || '').replace(/[‣\s]/g, '').slice(0, 40) || ('i' + i));
      var box = document.createElement('input');
      box.type = 'checkbox'; box.className = 'done-check';
      box.checked = localStorage.getItem(key) === '1';
      block.setAttribute('data-done', box.checked ? '1' : '0');
      box.addEventListener('click', function (e) { e.stopPropagation(); });
      box.addEventListener('change', function () {
        block.setAttribute('data-done', box.checked ? '1' : '0');
        localStorage.setItem(key, box.checked ? '1' : '0');
        updateBars();
      });
      sum.appendChild(box);
    });
  }
  function ensureBars() {
    document.querySelectorAll('.notion-tabs__panel').forEach(function (panel) {
      if (panel.querySelector(':scope > .done-progress')) return;
      var first = panel.querySelector(':scope > ' + SEL);
      if (!first) return;
      var bar = document.createElement('div');
      bar.className = 'done-progress';
      bar.innerHTML = '<div class="done-progress__inner"><div class="done-progress__track"><div class="done-progress__fill"></div></div><div class="done-progress__label"></div></div>';
      panel.insertBefore(bar, first);
    });
  }
  function updateBars() {
    document.querySelectorAll('.notion-tabs__panel').forEach(function (panel) {
      var bar = panel.querySelector(':scope > .done-progress'); if (!bar) return;
      var toggles = [].slice.call(panel.querySelectorAll(':scope > ' + SEL));
      var total = toggles.length; if (!total) return;
      var done = toggles.filter(function (t) { var c = t.querySelector('.done-check'); return c && c.checked; }).length;
      var pct = Math.round(done / total * 100);
      var fill = bar.querySelector('.done-progress__fill');
      var lab = bar.querySelector('.done-progress__label');
      var wasFull = bar.dataset.full === '1';
      var isFull = done === total;
      if (isFull && !wasFull && booted) party();
      bar.dataset.full = isFull ? '1' : '0';
      if (done === 0) { bar.classList.remove('is-on'); fill.style.width = '0%'; if (lab.textContent !== '') lab.textContent = ''; return; }
      bar.classList.add('is-on');
      if (fill.style.width !== pct + '%') fill.style.width = pct + '%';
      var txt = done + ' / ' + total + ' erledigt · ' + pct + '%';
      if (lab.textContent !== txt) lab.textContent = txt;
    });
  }
  function sync() { decorate(); ensureBars(); }
  function boot() { sync(); setTimeout(function () { updateBars(); booted = true; }, 80); }
  document.addEventListener('DOMContentLoaded', boot);
  boot();
  var t;
  window.__tsMO(function () { clearTimeout(t); t = setTimeout(function () { sync(); updateBars(); }, 150); })
    .observe(document.documentElement, { childList: true, subtree: true });
})();

