      svg.setAttribute('viewBox','0 0 '+wrap.clientWidth+' '+wrap.clientHeight);
      var pa=pos(a,wrap), pb=pos(b,wrap);
      var ax=pa.x+a.offsetWidth+10, ay=pa.y+a.offsetHeight/2;
