      /* Menü darf nie unten aus der Karte ragen -> dynamisch hochklemmen */
      var wr=win.getBoundingClientRect(), mr=menu.getBoundingClientRect(); var over=mr.bottom-(wr.bottom-12);
      if(over>0) menu.style.top=(tr[1]-over)+'px';
