      el.querySelector('.l3-fill').style.transform='scaleX(.8)'; el.querySelector('.l3-clock').textContent='14:30';
      el.querySelectorAll('.l3-pr b').forEach(function(b){ b.textContent=b.getAttribute('data-v'); });
      setVals(el,4);
